import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  buttonGroupClassName,
  buttonGroupClassNameByOrientation,
  buttonGroupItemClassName,
  buttonGroupSeparatorClassName,
  buttonGroupTextClassName,
} from "./view";
import type { ButtonGroupOrientation } from "./view";

export type { ButtonGroupOrientation };

export {
  buttonGroupClassName,
  buttonGroupClassNameByOrientation,
  buttonGroupItemClassName,
  buttonGroupSeparatorClassName,
  buttonGroupTextClassName,
} from "./view";

export type ViewConfig = Readonly<{
  children: readonly (Html | string)[];
  orientation?: ButtonGroupOrientation;
  ariaLabel?: string;
  className?: string;
}>;

export type ItemViewConfig = Readonly<{
  children: readonly (Html | string)[];
  className?: string;
}>;

export type SeparatorViewConfig = Readonly<{
  orientation?: ButtonGroupOrientation;
  className?: string;
}>;

export type TextViewConfig = Readonly<{
  children: readonly (Html | string)[];
  className?: string;
}>;

const classNames = (base: string, className?: string): string =>
  [base, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

export const view = <ParentMessage>({
  children,
  orientation = "horizontal",
  ariaLabel,
  className,
}: ViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("role", "group"),
      h.DataAttribute("slot", "button-group"),
      h.DataAttribute("orientation", orientation),
      h.Class(
        classNames(
          `${buttonGroupClassName} ${buttonGroupClassNameByOrientation(orientation)}`,
          className
        )
      ),
      ...(ariaLabel === undefined ? [] : [h.AriaLabel(ariaLabel)]),
    ],
    children
  );
};

export const itemView = <ParentMessage>({
  children,
  className,
}: ItemViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.DataAttribute("slot", "button-group-item"),
      h.Class(classNames(buttonGroupItemClassName, className)),
    ],
    children
  );
};

export const separatorView = <ParentMessage>({
  orientation = "horizontal",
  className,
}: SeparatorViewConfig = {}): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("role", "separator"),
      h.AriaHidden(true),
      h.DataAttribute("slot", "button-group-separator"),
      h.DataAttribute("orientation", orientation),
      h.Class(classNames(buttonGroupSeparatorClassName, className)),
    ],
    []
  );
};

export const textView = <ParentMessage>({
  children,
  className,
}: TextViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.span(
    [
      h.DataAttribute("slot", "button-group-text"),
      h.Class(classNames(buttonGroupTextClassName, className)),
    ],
    children
  );
};

export type ButtonGroupOrientation = "horizontal" | "vertical";

export const buttonGroupClassName =
  "inline-flex isolate items-stretch overflow-hidden rounded-lg border border-gray-300 bg-white shadow-sm";

export const buttonGroupClassNameByOrientation = (
  orientation: ButtonGroupOrientation = "horizontal"
): string => {
  if (orientation === "vertical") {
    return "flex-col divide-y divide-gray-200";
  }

  return "flex-row divide-x divide-gray-200";
};

export const buttonGroupItemClassName =
  "relative z-0 flex min-w-0 items-stretch focus-within:z-10";

export const buttonGroupSeparatorClassName =
  "shrink-0 self-stretch bg-gray-200 data-[orientation=horizontal]:h-auto data-[orientation=horizontal]:w-px data-[orientation=vertical]:h-px data-[orientation=vertical]:w-auto";

export const buttonGroupTextClassName =
  "inline-flex items-center justify-center whitespace-nowrap bg-gray-50 px-3 text-sm font-medium text-gray-500";

import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { describe, test } from "vitest";

import * as ButtonGroup from "./index";

describe("ButtonGroup registry view", () => {
  test("renders a labelled horizontal group", () => {
    const view = (): Html => {
      const h = html<never>();

      return ButtonGroup.view<never>({
        ariaLabel: "Report actions",
        children: [
          ButtonGroup.itemView<never>({
            children: [h.button([], ["Archive Report"])],
          }),
          ButtonGroup.itemView<never>({
            children: [h.button([], ["Snooze"])],
          }),
        ],
      });
    };

    Scene.scene(
      {
        update: (model: undefined): readonly [undefined, []] => [model, []],
        view,
      },
      Scene.with(undefined),
      Scene.expect(Scene.role("group", { name: "Report actions" })).toExist(),
      Scene.expect(Scene.role("button", { name: "Archive Report" })).toExist(),
      Scene.expect(Scene.role("button", { name: "Snooze" })).toExist()
    );
  });

  test("renders vertical orientation and inert separators", () => {
    const view = (): Html => {
      const h = html<never>();

      return ButtonGroup.view<never>({
        orientation: "vertical",
        ariaLabel: "Vertical actions",
        children: [
          ButtonGroup.itemView<never>({ children: [h.button([], ["Plus"])] }),
          ButtonGroup.separatorView<never>({ orientation: "vertical" }),
          ButtonGroup.itemView<never>({ children: [h.button([], ["Minus"])] }),
        ],
      });
    };

    Scene.scene(
      {
        update: (model: undefined): readonly [undefined, []] => [model, []],
        view,
      },
      Scene.with(undefined),
      Scene.expect(
        Scene.role("group", { name: "Vertical actions" })
      ).toHaveAttr("data-orientation", "vertical"),
      Scene.expect(Scene.role("separator")).toHaveAttr("aria-hidden", "true")
    );
  });
});
